#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long a;
    long long b;
    cin >> a >> b;

    long long x = a, y = b;
    while (y != 0) {
        long long rest = x % y;
        x = y;
        y = rest;
    }
    cout << a / x * b << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        long b = sc.nextLong();

        long x = a, y = b;
        while (y != 0) {
            long rest = x % y;
            x = y;
            y = rest;
        }
        System.out.println(a / x * b);
    }
}
